CREATE OR REPLACE FUNCTION finance_apm_private.command(cmd text, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare before_actor jsonb;after_actor jsonb;result jsonb;m finance_apm_private.metric_mappings;c text;
begin
 before_actor:=finance_apm_private.fresh_actor(p->>'entityId');
 result:=finance_apm_private.command_before_fresh_authorization(cmd,p);
 -- Separate SQL commands inside a VOLATILE function obtain a fresh snapshot;
 -- this must not be replaced by a STABLE helper or a cached pre-lock record.
 after_actor:=finance_apm_private.fresh_actor(p->>'entityId');
 if after_actor->>'actorId' is distinct from before_actor->>'actorId' or after_actor->>'tenantId' is distinct from before_actor->>'tenantId' then raise exception 'FINANCE_APM_AUTHORITY_CHANGED' using errcode='42501';end if;
 if cmd in('mapping.verify','mapping.revoke') and after_actor->>'role'<>'ceo' then raise exception 'FINANCE_APM_AUTHORITY_CHANGED' using errcode='42501';end if;
 if cmd<>'list' then
  select * into m from finance_apm_private.metric_mappings where id=coalesce(nullif(p->>'mappingId',''),result->>'mappingId')::uuid and tenant_id=(after_actor->>'tenantId')::uuid and entity_id=p->>'entityId';
  if m.id is null then raise exception 'FINANCE_APM_AUTHORITY_CHANGED' using errcode='42501';end if;
  perform private.finance_reporting_department_v1(m.tenant_id,m.entity_id,m.department_code);
  foreach c in array m.account_codes loop perform private.finance_reporting_account_v1(m.tenant_id,c);end loop;
  if cmd in('mapping.verify','snapshot.preview','snapshot.approve') and not finance_apm_private.active(m) then raise exception 'FINANCE_APM_AUTHORITY_CHANGED' using errcode='42501';end if;
  if cmd='snapshot.approve' and not exists(
   select 1 from finance_apm_private.commands x join public.finance_users f on f.tenant_id=x.tenant_id and f.id=x.actor_id
   where x.tenant_id=m.tenant_id and x.actor_id<>after_actor->>'actorId' and f.active and f.role in('accountant','ceo') and f.auth_user_id is not null
    and x.result->>'previewHash'=p->>'previewHash' and x.result->'evidence'->>'mappingId'=m.id::text
    and x.result->'evidence'->>'year'=p->>'year' and x.result->'evidence'->>'quarter'=p->>'quarter'
  ) then raise exception 'FINANCE_APM_AUTHORITY_CHANGED' using errcode='42501';end if;
 end if;
 return result;
end $function$

CREATE OR REPLACE FUNCTION finance_apm_private.command_before_fresh_authorization(cmd text, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a jsonb;t uuid;u text;m finance_apm_private.metric_mappings;c text;begin
 -- Reauthorize before every replay. Old receipts do not restore revoked access.
 a:=finance_apm_private.actor(p->>'entityId');t:=(a->>'tenantId')::uuid;u:=a->>'actorId';
 if cmd='mapping.propose' then
  perform private.finance_reporting_department_v1(t,p->>'entityId',p->>'departmentCode');
  if jsonb_typeof(p->'accountCodes')='array' then
   for c in select jsonb_array_elements_text(p->'accountCodes') loop perform private.finance_reporting_account_v1(t,c);end loop;
  end if;
 elsif cmd in('mapping.verify','snapshot.preview','snapshot.approve') then
  select * into m from finance_apm_private.metric_mappings where id=(p->>'mappingId')::uuid and tenant_id=t and entity_id=p->>'entityId';
  if m.id is null then raise exception 'FINANCE_APM_FORBIDDEN' using errcode='42501';end if;
  perform private.finance_reporting_department_v1(t,m.entity_id,m.department_code);
  foreach c in array m.account_codes loop perform private.finance_reporting_account_v1(t,c);end loop;
  if cmd='snapshot.approve' and not exists(
   select 1 from finance_apm_private.commands x join public.finance_users f on f.tenant_id=x.tenant_id and f.id=x.actor_id
   where x.tenant_id=t and x.actor_id<>u and f.active and f.role in('accountant','ceo') and f.auth_user_id is not null
    and x.result->>'previewHash'=p->>'previewHash' and x.result->'evidence'->>'mappingId'=m.id::text
    and x.result->'evidence'->>'year'=p->>'year' and x.result->'evidence'->>'quarter'=p->>'quarter'
  ) then raise exception 'FINANCE_APM_INDEPENDENT_REVIEW_REQUIRED' using errcode='42501';end if;
 end if;
 return finance_apm_private.command_before_workbench(cmd,p);
end $function$

CREATE OR REPLACE FUNCTION finance_apm_private.command_before_workbench(cmd text, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a jsonb;t uuid;u text;rid uuid;h text;old finance_apm_private.commands;m finance_apm_private.metric_mappings;
 result jsonb;ev jsonb;snap jsonb;sid uuid;y integer;q integer;i integer;codes text[];
begin
 if jsonb_typeof(p) is distinct from 'object' or octet_length(p::text)>65536 or cmd<>all(array['mapping.propose','mapping.verify','mapping.revoke','snapshot.preview','snapshot.approve','list']) then raise exception 'FINANCE_APM_INPUT_INVALID';end if;
 if exists(select 1 from jsonb_object_keys(p) k where k<>all(array['requestId','entityId','mappingId','apmCompanyId','apmDepartmentId','departmentCode','accountCodes','reference','year','quarter','previewHash'])) then raise exception 'FINANCE_APM_INPUT_INVALID';end if;
 a:=finance_apm_private.actor(p->>'entityId');t:=(a->>'tenantId')::uuid;u:=a->>'actorId';
 if cmd='list' then
  return jsonb_build_object('mappings',coalesce((select jsonb_agg(to_jsonb(x)||jsonb_build_object('verified',finance_apm_private.active(x))) from finance_apm_private.metric_mappings x where x.tenant_id=t and x.entity_id=p->>'entityId'),'[]'));
 end if;
 rid:=(p->>'requestId')::uuid;if rid is null then raise exception 'FINANCE_APM_REQUEST_REQUIRED';end if;
 h:=finance_apm_private.hash(jsonb_build_object('command',cmd,'payload',p));
 perform pg_advisory_xact_lock(hashtextextended(t::text||u||rid::text,831));
 select * into old from finance_apm_private.commands where tenant_id=t and actor_id=u and request_id=rid;
 if old.request_id is not null then if old.payload_hash<>h then raise exception 'FINANCE_APM_REPLAY_CONFLICT';end if;return old.result;end if;
 if cmd='mapping.propose' then
  if jsonb_typeof(p->'accountCodes') is distinct from 'array' or jsonb_array_length(p->'accountCodes') not between 1 and 50
   or exists(select 1 from jsonb_array_elements(p->'accountCodes') x where jsonb_typeof(x)<>'string' or (x#>>'{}')!~'^4[0-9A-Za-z_-]{0,19}$') then raise exception 'FINANCE_APM_REVENUE_ACCOUNTS_REQUIRED';end if;
  select array_agg(distinct x order by x) into codes from jsonb_array_elements_text(p->'accountCodes') x;
  if cardinality(codes)<>jsonb_array_length(p->'accountCodes') or length(btrim(coalesce(p->>'reference',''))) not between 10 and 1000
   or (p->>'apmCompanyId')::uuid is null or (p->>'apmDepartmentId')::uuid is null then raise exception 'FINANCE_APM_MAPPING_INVALID';end if;
  if not exists(select 1 from public.system_settings s cross join lateral jsonb_array_elements(case when jsonb_typeof(s.value)='array' then s.value else '[]' end) d
   where s.tenant_id=t and s.key='departments' and d->>'c'=p->>'departmentCode') then raise exception 'FINANCE_APM_DEPARTMENT_UNVERIFIED';end if;
  insert into finance_apm_private.metric_mappings(tenant_id,apm_company_id,apm_department_id,entity_id,department_code,account_codes,reference,created_by)
   values(t,(p->>'apmCompanyId')::uuid,(p->>'apmDepartmentId')::uuid,p->>'entityId',p->>'departmentCode',codes,btrim(p->>'reference'),u) returning * into m;
  result:=jsonb_build_object('mappingId',m.id,'status','pending_verification');
 else
  select * into m from finance_apm_private.metric_mappings where id=(p->>'mappingId')::uuid and tenant_id=t and entity_id=p->>'entityId';
  if m.id is null then raise exception 'FINANCE_APM_FORBIDDEN' using errcode='42501';end if;
  perform pg_advisory_xact_lock(hashtextextended(m.apm_company_id::text||m.apm_department_id::text,832));
  if cmd in('mapping.verify','mapping.revoke') then
   if public.current_finance_role()<>'ceo' or (cmd='mapping.verify' and m.created_by=u) then raise exception 'FINANCE_APM_INDEPENDENT_REVIEW_REQUIRED' using errcode='42501';end if;
   if length(btrim(coalesce(p->>'reference',''))) not between 10 and 1000 then raise exception 'FINANCE_APM_REFERENCE_REQUIRED';end if;
   if cmd='mapping.verify' and exists(select 1 from finance_apm_private.metric_mappings x where x.apm_company_id=m.apm_company_id and x.apm_department_id=m.apm_department_id and x.id<>m.id and finance_apm_private.active(x)) then raise exception 'FINANCE_APM_MAPPING_CONFLICT';end if;
   insert into finance_apm_private.mapping_decisions(mapping_id,decision,actor_id,reference) values(m.id,case cmd when 'mapping.verify' then 'verified' else 'revoked' end,u,btrim(p->>'reference'));
   result:=jsonb_build_object('mappingId',m.id,'status',case cmd when 'mapping.verify' then 'verified' else 'revoked' end);
  else
   y:=(p->>'year')::integer;q:=(p->>'quarter')::integer;
   if y is null or q is null then raise exception 'FINANCE_APM_PERIOD_INVALID';end if;
   -- Same lock domain and order as canonical ledger/period-close writes.
   for i in 0..2 loop perform pg_advisory_xact_lock(hashtextextended('finance_period|'||t::text||'|production|'||m.entity_id||'|'||to_char(make_date(y,(q-1)*3+1,1)+make_interval(months=>i),'YYYY-MM'),0));end loop;
   ev:=finance_apm_private.evidence(m,y,q);h:=finance_apm_private.hash(ev);
   if cmd='snapshot.preview' then result:=jsonb_build_object('previewHash',h,'evidence',ev);
   else
    if p->>'previewHash' is distinct from h then raise exception 'FINANCE_APM_SOURCE_CHANGED' using errcode='40001';end if;
    if exists(select 1 from finance_apm_private.metric_snapshots where mapping_id=m.id and year=y and quarter=q) then raise exception 'FINANCE_APM_SNAPSHOT_EXISTS';end if;
    sid:=gen_random_uuid();snap:=jsonb_build_object('snapshotId',sid,'metricKey','quarterly_closed_revenue_twd','value',ev->'value','currency','TWD',
     'scope',jsonb_build_object('kind','department','companyId',m.apm_company_id,'departmentId',m.apm_department_id),
     'period',jsonb_build_object('year',y,'quarter',q,'startDate',ev->'startDate','endDate',ev->'endDate'),'closedAt',clock_timestamp());
    snap:=snap||jsonb_build_object('hash',finance_apm_private.hash(snap));
    insert into finance_apm_private.metric_snapshots(id,mapping_id,year,quarter,preview_hash,source_evidence,snapshot,approved_by) values(sid,m.id,y,q,h,ev,snap,u);
    result:=jsonb_build_object('status','approved','snapshot',snap);
   end if;
  end if;
 end if;
 -- Recompute command hash: the preview hash is a different domain.
 insert into finance_apm_private.commands values(t,u,rid,finance_apm_private.hash(jsonb_build_object('command',cmd,'payload',p)),result,clock_timestamp());
 return result;
end $function$

CREATE OR REPLACE FUNCTION finance_apm_private.correction_command(cmd text, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare before_actor public.finance_users;after_actor public.finance_users;result jsonb;o finance_hr_private.finance_hr_obligations;proposal finance_apm_private.correction_proposals;
begin
 before_actor:=public.current_finance_user();
 result:=finance_apm_private.correction_command_before_fresh_authorization(cmd,p);
 if not finance_apm_private.fresh_session() then raise exception 'FINANCE_APM_AUTHORITY_CHANGED' using errcode='42501';end if;
 after_actor:=public.current_finance_user();
 if auth.uid() is null or after_actor.id is null or after_actor.auth_user_id is distinct from auth.uid() or after_actor.active is distinct from true or after_actor.role not in('accountant','ceo') or after_actor.id is distinct from before_actor.id or after_actor.tenant_id is distinct from before_actor.tenant_id then raise exception 'FINANCE_APM_AUTHORITY_CHANGED' using errcode='42501';end if;
 if cmd='list' then
  if exists(select 1 from jsonb_array_elements(result->'proposals')x join finance_hr_private.finance_hr_obligations f on f.obligation_id=(x->>'obligation_id')::uuid where not finance_hr_private.finance_hr_reader(f.tenant_id,f.source_employer_id,after_actor.id)) then raise exception 'FINANCE_APM_AUTHORITY_CHANGED' using errcode='42501';end if;
 else
  if cmd='verify' then
   select * into proposal from finance_apm_private.correction_proposals where id=(p->>'proposalId')::uuid;
   select * into o from finance_hr_private.finance_hr_obligations where obligation_id=proposal.obligation_id;
  else select * into o from finance_hr_private.finance_hr_obligations where obligation_id=(p->>'obligationId')::uuid;end if;
  if o.obligation_id is null or o.tenant_id is distinct from after_actor.tenant_id or not finance_hr_private.finance_hr_reader(o.tenant_id,o.source_employer_id,after_actor.id) then raise exception 'FINANCE_APM_AUTHORITY_CHANGED' using errcode='42501';end if;
 end if;
 return result;
end $function$

CREATE OR REPLACE FUNCTION finance_apm_private.correction_command_before_fresh_authorization(cmd text, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a public.finance_users;o finance_hr_private.finance_hr_obligations;proposal finance_apm_private.correction_proposals;
 old finance_apm_private.commands;req uuid;h text;ev jsonb;receipt jsonb;result jsonb;receipt_id uuid:=gen_random_uuid();begin
 if jsonb_typeof(p) is distinct from 'object' or octet_length(p::text)>32768 or cmd<>all(array['propose','verify','list'])
  or exists(select 1 from jsonb_object_keys(p) k where k<>all(array['requestId','obligationId','correctionBatchId','correctionSourceHash','originalBatchId','reversalVoucherId','refund','reference','proposalId'])) then raise exception 'FINANCE_APM_CORRECTION_INPUT_INVALID';end if;
 if not public.finance_auth_session_active() then raise exception 'FINANCE_APM_FORBIDDEN' using errcode='42501';end if;
 a:=public.current_finance_user();
 if auth.uid() is null or a.auth_user_id is distinct from auth.uid() or not a.active or a.role not in('accountant','ceo') then raise exception 'FINANCE_APM_FORBIDDEN' using errcode='42501';end if;
 if cmd='list' then
  return jsonb_build_object('proposals',coalesce((select jsonb_agg(to_jsonb(c)||jsonb_build_object('receipt',(select receipt from finance_apm_private.correction_receipts where proposal_id=c.id)) order by c.created_at desc)
   from finance_apm_private.correction_proposals c join finance_hr_private.finance_hr_obligations x on x.obligation_id=c.obligation_id
   where c.tenant_id=a.tenant_id and finance_hr_private.finance_hr_reader(x.tenant_id,x.source_employer_id,a.id)),'[]'));
 end if;
 if cmd='verify' then select * into proposal from finance_apm_private.correction_proposals where id=(p->>'proposalId')::uuid and tenant_id=a.tenant_id;
  select * into o from finance_hr_private.finance_hr_obligations where obligation_id=proposal.obligation_id;
 else select * into o from finance_hr_private.finance_hr_obligations where obligation_id=(p->>'obligationId')::uuid;end if;
 if o.obligation_id is null or o.tenant_id<>a.tenant_id or not finance_hr_private.finance_hr_reader(o.tenant_id,o.source_employer_id,a.id) then raise exception 'FINANCE_APM_FORBIDDEN' using errcode='42501';end if;
 req:=(p->>'requestId')::uuid;
 if req is null or length(btrim(coalesce(p->>'reference',''))) not between 10 and 1000 then raise exception 'FINANCE_APM_CORRECTION_REFERENCE_REQUIRED';end if;
 h:=finance_apm_private.hash(jsonb_build_object('correctionCommand',cmd,'payload',p));
 perform pg_advisory_xact_lock(hashtextextended(a.tenant_id::text||a.id||req::text,831));
 perform pg_advisory_xact_lock(hashtextextended(o.obligation_id::text,617));
 select * into old from finance_apm_private.commands where tenant_id=a.tenant_id and actor_id=a.id and request_id=req;
 if found then if old.payload_hash<>h then raise exception 'FINANCE_APM_REPLAY_CONFLICT';end if;return old.result;end if;
 if cmd='propose' then
  if (p->>'correctionBatchId')::uuid is null or (p->>'originalBatchId')::uuid is null or p->>'correctionBatchId'=p->>'originalBatchId'
   or coalesce(p->>'correctionSourceHash','')!~'^[0-9a-f]{64}$' or jsonb_typeof(p->'refund') is distinct from 'object'
   or (select count(*) from jsonb_object_keys(p->'refund'))<>4 or exists(select 1 from jsonb_object_keys(p->'refund') k where k<>all(array['status','amountCents','reference','sha256']))
   or p->'refund'->>'status' is distinct from 'settled' or p->'refund'->>'amountCents' is distinct from o.total_net_cents::text
   or length(btrim(coalesce(p->'refund'->>'reference',''))) not between 10 and 500 or coalesce(p->'refund'->>'sha256','')!~'^[0-9a-f]{64}$'
  then raise exception 'FINANCE_APM_REFUND_EVIDENCE_REQUIRED';end if;
  ev:=finance_apm_private.correction_evidence(o,p->>'reversalVoucherId');
  insert into finance_apm_private.correction_proposals(tenant_id,obligation_id,correction_batch_id,correction_source_hash,original_batch_id,reversal_voucher_id,refund,proposed_by,reference,source_evidence,evidence_hash)
   values(a.tenant_id,o.obligation_id,(p->>'correctionBatchId')::uuid,p->>'correctionSourceHash',(p->>'originalBatchId')::uuid,p->>'reversalVoucherId',p->'refund',a.id,btrim(p->>'reference'),ev,finance_apm_private.hash(ev)) returning * into proposal;
  result:=jsonb_build_object('proposalId',proposal.id,'status','pending_independent_verification');
 else
  if proposal.proposed_by=a.id then raise exception 'FINANCE_APM_INDEPENDENT_REVIEW_REQUIRED' using errcode='42501';end if;
  ev:=finance_apm_private.correction_evidence(o,proposal.reversal_voucher_id);
  if finance_apm_private.hash(ev)<>proposal.evidence_hash then raise exception 'FINANCE_APM_SOURCE_CHANGED' using errcode='40001';end if;
  receipt:=jsonb_build_object('schemaVersion',1,'kind','finance_bonus_reversal','receiptId',receipt_id,'correctionBatchId',proposal.correction_batch_id,
   'correctionSourceHash',proposal.correction_source_hash,'originalBatchId',proposal.original_batch_id,'obligationId',o.obligation_id,'flowId',o.flow_id,'sourceEmployerId',o.source_employer_id,
   'originalSettlementHash',o.source_hash,'originalVoucherId',ev->'originalVoucherId','reversalVoucherId',proposal.reversal_voucher_id,'originalNetCents',o.total_net_cents,
   'ledgerHash',proposal.evidence_hash,'refund',proposal.refund,'proposedBy',proposal.proposed_by,'verifiedBy',a.id,'verifiedAt',clock_timestamp());
  receipt:=receipt||jsonb_build_object('receiptHash',finance_apm_private.hash(receipt));
  insert into finance_apm_private.correction_receipts(id,proposal_id,receipt,verified_by) values(receipt_id,proposal.id,receipt,a.id);
  result:=jsonb_build_object('status','verified','receipt',receipt);
 end if;
 insert into finance_apm_private.commands values(a.tenant_id,a.id,req,h,result,clock_timestamp());return result;end $function$

CREATE OR REPLACE FUNCTION finance_apm_private.correction_export(receipt_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r finance_apm_private.correction_receipts;p finance_apm_private.correction_proposals;o finance_hr_private.finance_hr_obligations;begin
 select * into r from finance_apm_private.correction_receipts where id=receipt_id;
 select * into p from finance_apm_private.correction_proposals where id=r.proposal_id;
 select * into o from finance_hr_private.finance_hr_obligations where obligation_id=p.obligation_id;
 if r.id is null or finance_apm_private.hash(finance_apm_private.correction_evidence(o,p.reversal_voucher_id))<>p.evidence_hash then raise exception 'FINANCE_APM_RECEIPT_UNAVAILABLE';end if;
 return r.receipt;end $function$

CREATE OR REPLACE FUNCTION finance_apm_private.evidence(m finance_apm_private.metric_mappings, y integer, q integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare first_day date;last_day date;closes jsonb;ledger jsonb;total numeric;begin
 if y not between 2000 and 2200 or q not between 1 and 4 then raise exception 'FINANCE_APM_PERIOD_INVALID';end if;
 first_day:=make_date(y,(q-1)*3+1,1);last_day:=(first_day+interval '3 months')::date;
 if last_day>current_date then raise exception 'FINANCE_APM_PERIOD_NOT_ENDED';end if;
 if not finance_apm_private.active(m) then raise exception 'FINANCE_APM_MAPPING_UNVERIFIED';end if;
 select jsonb_agg(to_jsonb(c) order by c.period) into closes from public.period_closes c
 where c.tenant_id=m.tenant_id and c.entity_id=m.entity_id and c.data_environment='production'
 and c.period between to_char(first_day,'YYYY-MM') and to_char(last_day-1,'YYYY-MM') and c.status='closed';
 if jsonb_array_length(coalesce(closes,'[]'))<>3 or (select count(distinct c->>'period') from jsonb_array_elements(coalesce(closes,'[]')) c)<>3 then raise exception 'FINANCE_APM_CLOSED_QUARTER_REQUIRED';end if;
 select coalesce(jsonb_agg(to_jsonb(l) order by l.id),'[]'),coalesce(sum(l.credit-l.debit),0) into ledger,total
 from public.ledger_entries l where l.tenant_id=m.tenant_id and l.entity_id=m.entity_id and l.data_environment='production'
 and l.department_code=m.department_code and l.account_code=any(m.account_codes)
 and l.entry_date>=first_day and l.entry_date<last_day and l.voided_at is null
 and coalesce(l.source_type,'') not in('period_close','closing_entry','year_end_close');
 if total<0 or total>999999999999 or total<>round(total,4) then raise exception 'FINANCE_APM_REVENUE_RANGE';end if;
 return jsonb_build_object('mappingId',m.id,'year',y,'quarter',q,'startDate',first_day,'endDate',last_day-1,'value',total,
  'closeHash',finance_apm_private.hash(closes),'ledgerHash',finance_apm_private.hash(ledger),'ledgerCount',jsonb_array_length(ledger),'accountCodes',m.account_codes);
end $function$

CREATE OR REPLACE FUNCTION finance_apm_private.export_snapshots()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s finance_apm_private.metric_snapshots;m finance_apm_private.metric_mappings;ev jsonb;result jsonb:='[]';begin
 if (select count(*) from finance_apm_private.metric_snapshots)>500 then raise exception 'FINANCE_APM_EXPORT_LIMIT';end if;
 for s in select * from finance_apm_private.metric_snapshots order by approved_at,id loop
  select * into m from finance_apm_private.metric_mappings where id=s.mapping_id;
  if not finance_apm_private.active(m) then continue;end if;
  begin ev:=finance_apm_private.evidence(m,s.year,s.quarter);exception when sqlstate 'P0001' then continue;end;
  if finance_apm_private.hash(ev)=s.preview_hash then result:=result||jsonb_build_array(s.snapshot);end if;
 end loop;
 return jsonb_build_object('generatedAt',clock_timestamp(),'snapshots',result);
end $function$

CREATE OR REPLACE FUNCTION finance_apm_private.fresh_actor(entity text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare a public.finance_users; scope jsonb;
begin
 if not finance_apm_private.fresh_session() then raise exception 'FINANCE_APM_AUTHORITY_CHANGED' using errcode='42501';end if;
 a:=public.current_finance_user();
 if auth.uid() is null or a.id is null or a.auth_user_id is distinct from auth.uid() or a.active is distinct from true or a.role not in('accountant','ceo') then raise exception 'FINANCE_APM_AUTHORITY_CHANGED' using errcode='42501';end if;
 scope:=private.finance_reporting_actor_v1(entity,'production');
 if scope->>'actorId' is distinct from a.id or scope->>'tenantId' is distinct from a.tenant_id::text or (scope->>'canEditWorkpaper')::boolean is distinct from true then raise exception 'FINANCE_APM_AUTHORITY_CHANGED' using errcode='42501';end if;
 return scope||jsonb_build_object('role',a.role);
end $function$

CREATE OR REPLACE FUNCTION finance_apm_private.fresh_session()
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare sid uuid;begin
 begin sid:=nullif(auth.jwt()->>'session_id','')::uuid;exception when invalid_text_representation then return false;end;
 if sid is null or auth.uid() is null or not public.finance_auth_session_active() then return false;end if;
 return exists(select 1 from auth.sessions s where s.id=sid and s.user_id=auth.uid() and(s.not_after is null or s.not_after>clock_timestamp()));
end $function$

CREATE OR REPLACE FUNCTION finance_apm_private.workbench(entity text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a public.finance_users;authz jsonb;t uuid;e jsonb;entities jsonb:='[]';departments jsonb:='[]';accounts jsonb:='[]';
 mappings jsonb:='[]';periods jsonb:='[]';previews jsonb:='[]';snapshots jsonb:='[]';obligations jsonb:='[]';proposals jsonb:='[]';
 o finance_hr_private.finance_hr_obligations;v public.vouchers;original public.vouchers;reversals jsonb;ev jsonb;paid boolean;begin
 if not public.finance_auth_session_active() then raise exception 'FINANCE_APM_FORBIDDEN' using errcode='42501';end if;
 a:=public.current_finance_user();t:=a.tenant_id;
 if auth.uid() is null or a.auth_user_id is distinct from auth.uid() or not a.active or a.role not in('accountant','ceo') then raise exception 'FINANCE_APM_FORBIDDEN' using errcode='42501';end if;
 for e in select x from public.system_settings s cross join lateral jsonb_array_elements(case when jsonb_typeof(s.value)='array' then s.value else '[]' end) x where s.tenant_id=t and s.key='entities' loop
  if e->>'active'='false' then continue;end if;
  begin authz:=finance_apm_private.actor(e->>'id');exception when insufficient_privilege then continue;end;
  entities:=entities||jsonb_build_array(jsonb_build_object('id',e->>'id','name',coalesce(e->>'full',e->>'n',e->>'s',e->>'id')));
 end loop;
 if jsonb_array_length(entities)>100 then raise exception 'FINANCE_APM_WORKBENCH_LIMIT';end if;
 if entity is not null then
  authz:=finance_apm_private.actor(entity);
  if not exists(select 1 from jsonb_array_elements(entities) x where x->>'id'=entity) then raise exception 'FINANCE_APM_FORBIDDEN' using errcode='42501';end if;
  select coalesce(jsonb_agg(jsonb_build_object('code',d->>'c','name',coalesce(d->>'n',d->>'name',d->>'c')) order by d->>'c'),'[]') into departments
   from public.system_settings s cross join lateral jsonb_array_elements(case when jsonb_typeof(s.value)='array' then s.value else '[]' end) d
   where s.tenant_id=t and s.key='departments' and exists(select 1 from public.finance_department_units u join public.finance_department_entity_scopes scope on scope.tenant_id=u.tenant_id and scope.unit_id=u.id and scope.active where u.tenant_id=t and u.active and u.is_posting_unit and u.code=d->>'c' and scope.entity_code=entity);
  select coalesce(jsonb_agg(jsonb_build_object('code',coalesce(d->>'c',d->>'code'),'name',coalesce(d->>'n',d->>'name',d->>'c',d->>'code')) order by coalesce(d->>'c',d->>'code')),'[]') into accounts
   from public.system_settings s cross join lateral jsonb_array_elements(case when jsonb_typeof(s.value)='array' then s.value else '[]' end) d
   where s.tenant_id=t and s.key='accounts' and coalesce(d->>'c',d->>'code')~'^4[0-9A-Za-z_-]{0,19}$' and d->>'active' is distinct from 'false';
  select coalesce(jsonb_agg(to_jsonb(m)||jsonb_build_object('active',finance_apm_private.active(m),'proposerName',(select f.name from public.finance_users f where f.tenant_id=t and f.id=m.created_by),
    'decisions',coalesce((select jsonb_agg(jsonb_build_object('decision',d.decision,'actorName',f.name,'at',d.created_at,'reference',d.reference)) from finance_apm_private.mapping_decisions d left join public.finance_users f on f.tenant_id=t and f.id=d.actor_id where d.mapping_id=m.id),'[]')) order by m.created_at desc),'[]') into mappings from finance_apm_private.metric_mappings m where m.tenant_id=t and m.entity_id=entity;
  select coalesce(jsonb_agg(jsonb_build_object('year',y,'quarter',q) order by y desc,q desc),'[]') into periods from (
   select substring(period,1,4)::integer y,((substring(period,6,2)::integer-1)/3+1) q
   from public.period_closes where tenant_id=t and entity_id=entity and data_environment='production' and status='closed' and period~'^[0-9]{4}-(0[1-9]|1[0-2])$'
   group by 1,2 having count(distinct period)=3 and (make_date(substring(min(period),1,4)::integer,((substring(min(period),6,2)::integer-1)/3)*3+1,1)+interval '3 months')::date<=current_date
  ) complete;
  select coalesce(jsonb_agg(jsonb_build_object('id',x.request_id,'actorId',x.actor_id,'actorName',f.name,'createdAt',x.created_at,'previewHash',x.result->'previewHash','evidence',x.result->'evidence') order by x.created_at desc),'[]') into previews
   from finance_apm_private.commands x join finance_apm_private.metric_mappings m on m.id::text=x.result->'evidence'->>'mappingId' join public.finance_users f on f.id=x.actor_id and f.tenant_id=t
   where x.tenant_id=t and m.tenant_id=t and m.entity_id=entity and x.result ? 'previewHash' and f.active and f.role in('accountant','ceo') and finance_apm_private.active(m)
    and not exists(select 1 from finance_apm_private.metric_snapshots s where s.mapping_id=m.id and s.year::text=x.result->'evidence'->>'year' and s.quarter::text=x.result->'evidence'->>'quarter');
  select coalesce(jsonb_agg(jsonb_build_object('snapshot',s.snapshot,'approvedAt',s.approved_at,'approvedBy',(select f.name from public.finance_users f where f.tenant_id=t and f.id=s.approved_by),'mappingId',m.id) order by s.approved_at desc),'[]') into snapshots
   from finance_apm_private.metric_snapshots s join finance_apm_private.metric_mappings m on m.id=s.mapping_id where m.tenant_id=t and m.entity_id=entity;
  if (select count(*) from finance_hr_private.finance_hr_obligations x where x.tenant_id=t and x.legal_entity_code=entity and x.kind='bonus' and finance_hr_private.finance_hr_reader(t,x.source_employer_id,a.id))>200 then raise exception 'FINANCE_APM_WORKBENCH_LIMIT';end if;
  for o in select * from finance_hr_private.finance_hr_obligations x where x.tenant_id=t and x.legal_entity_code=entity and x.kind='bonus' and finance_hr_private.finance_hr_reader(t,x.source_employer_id,a.id) order by x.created_at desc loop
   select x.* into original from public.vouchers x join finance_hr_private.finance_hr_voucher_claims c on c.voucher_id=x.id where c.obligation_id=o.obligation_id;
   paid:=exists(select 1 from finance_hr_private.finance_hr_events x where x.obligation_id=o.obligation_id and x.action='bank_disbursement' and x.actor_system='finance');reversals:='[]';
   if paid and original.id is not null then
    for v in select * from public.vouchers x where x.tenant_id=t and x.entity_id=entity and x.data_environment='production' and x.adjusts_voucher_no=original.no and x.posted and x.voided_at is null
     and not exists(select 1 from finance_apm_private.correction_proposals c where c.reversal_voucher_id=x.id) order by x.no loop
     begin ev:=finance_apm_private.correction_evidence(o,v.id);exception when sqlstate 'P0001' then continue;end;
     reversals:=reversals||jsonb_build_array(jsonb_build_object('id',v.id,'number',v.no,'total',v.total));
    end loop;
   end if;
   obligations:=obligations||jsonb_build_array(jsonb_build_object('id',o.obligation_id,'flowId',o.flow_id,'period',o.period,'payDate',o.pay_date,'status',o.status,'paid',paid,'totalNetCents',o.total_net_cents,'originalVoucherNumber',original.no,'reversals',reversals));
  end loop;
  select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'obligationId',p.obligation_id,'period',ob.period,'proposerId',p.proposed_by,'proposerName',(select f.name from public.finance_users f where f.tenant_id=t and f.id=p.proposed_by),'createdAt',p.created_at,'reference',p.reference,'refund',p.refund,'originalBatchId',p.original_batch_id,'correctionBatchId',p.correction_batch_id,'correctionSourceHash',p.correction_source_hash,'reversalVoucherNumber',voucher.no,'receipt',r.receipt,'verifierName',(select f.name from public.finance_users f where f.tenant_id=t and f.id=r.verified_by)) order by p.created_at desc),'[]') into proposals
   from finance_apm_private.correction_proposals p join finance_hr_private.finance_hr_obligations ob on ob.obligation_id=p.obligation_id join public.vouchers voucher on voucher.id=p.reversal_voucher_id left join finance_apm_private.correction_receipts r on r.proposal_id=p.id
   where p.tenant_id=t and ob.legal_entity_code=entity and finance_hr_private.finance_hr_reader(t,ob.source_employer_id,a.id);
 end if;
 if jsonb_array_length(mappings)>200 or jsonb_array_length(previews)>500 or jsonb_array_length(snapshots)>500 or jsonb_array_length(proposals)>200 then raise exception 'FINANCE_APM_WORKBENCH_LIMIT';end if;
 return jsonb_build_object('actor',jsonb_build_object('id',a.id,'name',a.name,'role',a.role),'entityId',entity,'entities',entities,'departments',departments,'accounts',accounts,'mappings',mappings,'periods',periods,'previews',previews,'snapshots',snapshots,'obligations',obligations,'corrections',proposals);
end $function$
